parameters.jsCode:
const out = $input.first().json.output;
let raw = '';
if (Array.isArray(out)) {
  const msg = out.find(o => o && o.type === 'message') || out[0] || {};
  const part = (msg.content || []).find(c => c && c.type === 'output_text') || (msg.content || [])[0] || {};
  raw = part.text !== undefined ? part.text : '';
} else if (out !== undefined && out !== null) {
  raw = out;
}
let parsed = null;
if (raw && typeof raw === 'object') {
  parsed = raw;
} else {
  const text = String(raw);
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start !== -1 && end > start) {
    try { parsed = JSON.parse(text.slice(start, end + 1)); } catch (e) { parsed = null; }
  }
}
const rawText = typeof raw === 'string' ? raw : JSON.stringify(raw);
const userMsg = String($('User Input Webhook').first().json.body.message || '').toLowerCase();
const approvalPattern = /\b(approved?|approve it|looks good|looks great|lgtm|go ahead|proceed|move (on|forward|to)|next stage|next step|finali[sz]e|ready for (production|storyboard)|let'?s (continue|move|go)|ship it)\b/;
const revisionPattern = /\b(change|revise|rewrite|tweak|edit|instead|but|not quite|don'?t|shorter|longer|make it|try)\b/;
const userApproved = approvalPattern.test(userMsg) && !revisionPattern.test(userMsg);
const status = (userApproved || (parsed && String(parsed.status || '').toUpperCase() === 'PROCEED')) ? 'PROCEED' : 'REVIEW';
const response = (parsed && parsed.response) || rawText || 'Sorry, I could not generate a response. Please try again.';
const content = parsed && parsed.writing ? JSON.stringify(parsed.writing) : rawText;
return [{ json: { status, response, content } }];

